import { register, tryResolve } from "../contracts.js";
import { importFirstPartyExtensionModule } from "../first-party-import.js";
import { SkillDocumentParserProviderName, snapshotSkillDocumentParserProvider, } from "./skill-document-parser.js";
const DEFAULT_SKILL_PARSER_SOURCE_DIRECTORY = "ext-yaml";
const DEFAULT_SKILL_PARSER_EXTENSION_PACKAGE = "@veryfront/ext-yaml";
const DEFAULT_SKILL_PARSER_FACTORY_EXPORT = "createStdYamlSkillDocumentParserProvider";
let activation;
function readProviderFactory(extensionModule) {
    if (extensionModule === null ||
        (typeof extensionModule !== "object" && typeof extensionModule !== "function")) {
        throw new TypeError(`Invalid ${DEFAULT_SKILL_PARSER_EXTENSION_PACKAGE} module: expected a module namespace`);
    }
    let factory;
    try {
        factory = extensionModule
            .createStdYamlSkillDocumentParserProvider;
    }
    catch (cause) {
        throw new TypeError(`Invalid ${DEFAULT_SKILL_PARSER_EXTENSION_PACKAGE} module: could not read export "${DEFAULT_SKILL_PARSER_FACTORY_EXPORT}"`, { cause });
    }
    if (typeof factory !== "function") {
        throw new TypeError(`Invalid ${DEFAULT_SKILL_PARSER_EXTENSION_PACKAGE} module: export "${DEFAULT_SKILL_PARSER_FACTORY_EXPORT}" must be callable`);
    }
    return factory;
}
/** Load and capture the product distribution's extension-owned default parser. */
export async function loadDefaultSkillDocumentParserProvider() {
    const extensionModule = await importFirstPartyExtensionModule(DEFAULT_SKILL_PARSER_SOURCE_DIRECTORY, DEFAULT_SKILL_PARSER_EXTENSION_PACKAGE);
    return snapshotSkillDocumentParserProvider(readProviderFactory(extensionModule)());
}
async function activateDefaultSkillDocumentParser() {
    const provider = await loadDefaultSkillDocumentParserProvider();
    // Extension orchestration may have completed while the dynamic import was
    // pending. Preserve its generation-owned binding when present.
    if (tryResolve(SkillDocumentParserProviderName) === undefined) {
        register(SkillDocumentParserProviderName, provider);
    }
}
/**
 * Ensure the product distribution's first-party YAML extension owns the
 * default Skill parser contract without introducing its dependency into core.
 */
export async function ensureDefaultSkillDocumentParserContract() {
    if (tryResolve(SkillDocumentParserProviderName) !== undefined) {
        return;
    }
    activation ??= activateDefaultSkillDocumentParser().finally(() => {
        activation = undefined;
    });
    await activation;
}
/** Activate and capture the product distribution's immutable default parser generation. */
export async function getDefaultSkillDocumentParserProvider() {
    await ensureDefaultSkillDocumentParserContract();
    const provider = tryResolve(SkillDocumentParserProviderName);
    if (provider === undefined) {
        throw new TypeError("Default Skill document parser activation did not provide its contract");
    }
    return snapshotSkillDocumentParserProvider(provider);
}
